{"version":3,"sources":["powpow/general-purpose.css","powpow/general-purpose.scss"],"names":[],"mappings":"AAAA,gBAAgB;ACAhB;EAEI,6BAAA;ADCJ;;ACEA;;iDAAA;AAGA;EACI,kBAAA;EACA,gBAAA;EACA,aAAA;EACA,mBAAA;EACA,gBAAA;ADCJ;;ACEA;;iDAAA;AAGA;EACI,kBAAA;EACA,QAAA;EACA,SAAA;EACA,gCAAA;EACA,UAAA,EAAA,4CAAA;EACA,WAAA,EAAA,0CAAA;EACA,cAAA;EACA,iBAAA,EAAA,sBAAA;EACA,iBAAA,EAAA,oBAAA;EACA,UAAA;EACA,gBAAA;EACA,mBAAA,EAAA,mCAAA;EACA,gDAAA,EAAA,sBAAA;ADCJ;;ACEA;;iDAAA;AAGA;EACI,kBAAA;EACA,QAAA;EACA,SAAA;EACA,gCAAA;EACA,eAAA;EACA,gBAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,YAAA;ADCJ;;ACEA,kBAAA;AACA;EACI;IACI,eAAA;IACA,eAAA;EDCN;ECEE;IAEI,0BAAA;EDDN;ECIE;IAEI,YAAA;IACA,gBAAA;EDHN;ECME;IAEI,8BAAA;EDLN;AACF;ACOA;;;;CAAA;AAKA;EAEI;IACI,gBAAA;IACA,eAAA;IACA,kBAAA;IAEA,WAAA;IACA,YAAA;IACA,sDAAA,EAAA,sBAAA;EDPN;ECUE;IAEI,YAAA;IACA,gBAAA;EDTN;ECYE;IAEI,8BAAA;EDXN;ECaE;;;;GAAA;EAKA;IACI,eAAA;IACA,sCAAA;EDXN;ECcE;IACI,iBAAA;EDZN;ECeE;IACI,aAAA;EDbN;ECgBE;IACI,cAAA;EDdN;AACF;ACgBA;EAEI;IAEI,aAAA;EDhBN;ECmBE;IACI,iBAAA;EDjBN;AACF;ACwBA;;iDAAA;AAGA;EACI,kBAAA;EACA,UAAA;EACA,WAAA;ADtBJ;;ACyBA,yDAAA;AACA;EACI,cAAA;EACA,WAAA;ADtBJ;;ACyBA,oCAAA;AACA;;EAEI,YAAA;EACA,0CAAA;ADtBJ;;AC6BA;EACI,uBAAA;EACA,YAAA;EACA,UAAA;EACA,eAAA;EACA,cAAA,EAAA,4CAAA;EACA,aAAA,EAAA,oBAAA;EACA,oBAAA;EACA,mBAAA;EACA,QAAA;EACA,kDAAA;AD1BJ;;AC6BA;EACI,cAAA;AD1BJ;;AC6BA;EACI,eAAA;EACA,YAAA;EACA,SAAA;EACA,6CAAA;EACA,mBAAA;EACA,WAAA;EACA,kBAAA;EACA,mBAAA;EACA,kBAAA;EACA,gBAAA;EACA,qBAAA;EACA,2CAAA;EACA,UAAA;EACA,kDAAA;EACA,aAAA;EACA,oBAAA;EACA,mBAAA;AD1BJ;;AC6BA;EACI,UAAA;EACA,yCAAA;AD1BJ;;ACgCA,oDAAA;AACA,0CAAA;AACA;EACI;IACI,aAAA;ED7BN;EC+BE;IACI,eAAA;ED7BN;AACF;ACgCA;EACI;IACI,eAAA;ED9BN;ECgCE;IACI,aAAA;ED9BN;AACF;ACiCA;EAEI;IAEI,0BAAA;EDjCN;AACF;ACoCA;EACI;IACI,4BAAA;EDlCN;ECqCE;IACI,mBAAA;EDnCN;AACF","file":"general-purpose.css","sourcesContent":["@charset \"UTF-8\";\n.portfolio-options {\n  margin-bottom: 1em !important;\n}\n\n/* ============================================\n   BANNER: contenitore principale\n   ============================================ */\n.banner {\n  position: relative;\n  min-height: 70vh;\n  display: flex;\n  align-items: center;\n  overflow: hidden;\n}\n\n/* ============================================\n   VIDEO BACKGROUND: colonna centrata\n   ============================================ */\n.video-background {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 95%; /* 👈 LARGHEZZA DELLA COLONNA (regolabile) */\n  height: 95%; /* 👈 ALTEZZA DELLA COLONNA (regolabile) */\n  min-width: 70%;\n  max-width: 1200px; /* Larghezza massima */\n  max-height: 800px; /* Altezza massima */\n  z-index: 0;\n  overflow: hidden;\n  border-radius: 20px; /* Angoli arrotondati (opzionale) */\n  box-shadow: inset 0 10px 20px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n}\n\n/* ============================================\n   VIDEO: centrato e tagliato all'interno della colonna\n   ============================================ */\n.video-background video {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  min-width: 100%;\n  min-height: 100%;\n  width: auto;\n  height: auto;\n  object-fit: cover;\n  opacity: 60%;\n}\n\n/* Meta' schermo */\n@media (max-width: 720px) {\n  .video-background {\n    max-height: 80%;\n    max-width: 100%;\n  }\n  .banner .cd-headline {\n    font-size: 24px !important;\n  }\n  .section.banner {\n    padding: 0px;\n    min-height: 50vh;\n  }\n  body > section.portfolio > div > div.row.mb-5 {\n    margin-bottom: 15px !important;\n  }\n}\n/* \n==================================\nTelefono\n==================================\n*/\n@media (max-width: 520px) {\n  .video-background {\n    max-height: 100%;\n    max-width: 100%;\n    border-radius: 0px;\n    width: 100%;\n    height: 100%;\n    box-shadow: inset 0px 0px 30px 30px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n  }\n  .section.banner {\n    padding: 0px;\n    min-height: 30vh;\n  }\n  body > section.portfolio > div > div.row.mb-5 {\n    margin-bottom: 15px !important;\n  }\n  /*\n  ==================================\n  Portfolio-home\n  ==================================\n  */\n  label.btn {\n    font-size: 13px;\n    padding: 20px 10px 10px 0px !important;\n  }\n  p.short-text {\n    display: contents;\n  }\n  p.full-text {\n    display: none;\n  }\n  .stat {\n    font-size: 3vw;\n  }\n}\n@media (min-width: 521px) {\n  p.short-text {\n    display: none;\n  }\n  p.full-text {\n    display: contents;\n  }\n}\n/* ============================================\n   CONTENUTO TESTUALE: sopra il video\n   ============================================ */\n.banner .container {\n  position: relative;\n  z-index: 1;\n  width: 100%;\n}\n\n/* Colonna del testo centrata con larghezza controllata */\n.banner .container .col-lg-10 {\n  margin: 0 auto;\n  float: none;\n}\n\n/* Testo in contrasto con il video */\n.banner h2,\n.banner p {\n  color: white;\n  text-shadow: 0 2px 15px rgba(0, 0, 0, 0.7);\n}\n\n.copy-btn {\n  background: transparent;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n  color: inherit; /* Eredita il colore dal testo circostante */\n  font: inherit; /* Eredita il font */\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  transition: transform 0.2s ease, opacity 0.2s ease;\n}\n\n.copy-btn:hover {\n  color: #f44336;\n}\n\n.toast {\n  position: fixed;\n  bottom: 30px;\n  left: 50%;\n  transform: translateX(-50%) translateY(100px);\n  background: #ffffff;\n  color: #222;\n  padding: 14px 32px;\n  border-radius: 30px;\n  font-size: 0.95rem;\n  font-weight: 500;\n  letter-spacing: 0.3px;\n  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.35);\n  opacity: 0;\n  transition: opacity 0.4s ease, transform 0.4s ease;\n  z-index: 9999;\n  pointer-events: none;\n  white-space: nowrap;\n}\n\n.toast.show {\n  opacity: 1;\n  transform: translateX(-50%) translateY(0);\n}\n\n/* Cambiano in base alla grandezza del dispositivo */\n/* Su schermi piccoli, abbrevia il testo */\n@media (max-width: 768px) {\n  .stat .full-text {\n    display: none;\n  }\n  .stat .short-text {\n    display: inline;\n  }\n}\n@media (min-width: 769px) {\n  .stat .full-text {\n    display: inline;\n  }\n  .stat .short-text {\n    display: none;\n  }\n}\n@media (max-width: 991px) {\n  .footer-widget {\n    margin-top: 1em !important;\n  }\n}\n@media (max-width: 768px) {\n  .navbar-nav {\n    flex-wrap: nowrap !important;\n  }\n  .navbar-nav .nav-item {\n    white-space: nowrap;\n  }\n}",".portfolio-options\n{\n    margin-bottom: 1em !important;\n}\n\n/* ============================================\n   BANNER: contenitore principale\n   ============================================ */\n.banner {\n    position: relative;\n    min-height: 70vh;\n    display: flex;\n    align-items: center;\n    overflow: hidden;\n}\n\n/* ============================================\n   VIDEO BACKGROUND: colonna centrata\n   ============================================ */\n.video-background {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    width: 95%;              /* 👈 LARGHEZZA DELLA COLONNA (regolabile) */\n    height: 95%;             /* 👈 ALTEZZA DELLA COLONNA (regolabile) */\n    min-width: 70%;\n    max-width: 1200px;       /* Larghezza massima */\n    max-height: 800px;       /* Altezza massima */\n    z-index: 0;\n    overflow: hidden;\n    border-radius: 20px;     /* Angoli arrotondati (opzionale) */\n    box-shadow: inset 0 10px 20px rgba(0, 0, 0, 0.5); /* Ombra (opzionale) */\n}\n\n/* ============================================\n   VIDEO: centrato e tagliato all'interno della colonna\n   ============================================ */\n.video-background video {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%, -50%);\n    min-width: 100%;\n    min-height: 100%;\n    width: auto;\n    height: auto;\n    object-fit: cover;\n    opacity: 60%;\n}\n\n/* Meta' schermo */\n@media (max-width